  "result": "{\"case_id\": \"case_009\", \"case_number\": \"(2025)沪0115民初11876号\", \"title\": \"吴某诉某金融公司竞业限制补偿金纠纷案\", \"court_id\": \"court_sh_pudong\", \"court_name\": \"上海市浦东新区人民法院\", \"case_type\": \"劳动争议\", \"cause\": \"竞业限制\", \"judgment_date\": \"2025-10-27\", \"parties\": \"原告：吴某（员工）；被告：某金融公司\", \"summary\": \"双方约定竞业限制但公司未支付补偿，员工主张补偿金，法院判决按月支付竞业限制经济补偿。\", \"facts\": \"吴某2021年入职被告任研发主管，月工资30000元，离职时签订竞业限制协议约定期限一年。离职后吴某遵守竞业限制义务，但被告未支付任何补偿。\", \"reasoning\": \"竞业限制期间用人单位应按月支付经济补偿；未约定补偿数额的，按劳动者离职前十二个月平均工资的百分之三十按月支付，且不低于最低工资标准。\", \"holding\": \"约定竞业限制而未约定经济补偿的，劳动者履行义务后有权主张按离职前月均工资百分之三十的标准按月支付补偿。\", \"ruling\": \"一、被告支付吴某竞业限制经济补偿金人民币108000元（30000元×30%×12个月）；二、驳回其余请求。\", \"outcome\": \"部分支持\", \"keywords\": [\"竞业限制\", \"补偿金\", \"研发主管\", \"百分之三十\", \"离职\"]}"
}

structuredContent:
{
  "result": "{\"case_id\": \"lcase_015\", \"case_number\": \"(2022)沪9014民初20518号\", \"title\": \"章某诉某物流公司竞业限制纠纷案\", \"court_id\": \"court_sh_xuhui\", \"court_name\": \"上海市徐汇区人民法院\", \"case_type\": \"劳动争议\", \"cause\": \"竞业限制\", \"judgment_date\": \"2022-10-01\", \"parties\": \"原告：章某（员工）；被告：某物流公司\", \"summary\": \"补偿连续三个月未付，劳动者有权请求解除竞业约定。\", \"facts\": \"章某2015年入职被告任人事专员，月工资10900元。约定竞业限制未支付补偿，员工主张补偿金，法院酌情支持。公司确认解除后未实际支付竞业限制补偿。\", \"reasoning\": \"用人单位原因导致三个月未支付经济补偿的，劳动者有权请求解除竞业限制约定。本案被告自解除之日起未作任何给付，原告的解除请求于法有据。\", \"holding\": \"因用人单位原因三个月未付补偿的，劳动者有权请求解除竞业限制约定。\", \"ruling\": \"一、被告支付章某相关款项人民币76300元；二、案件受理费由被告负担。\", \"outcome\": \"部分支持\", \"keywords\": [\"竞业限制\", \"补偿金\", \"离职\"]}"
}

structuredContent:
{
  "result": "{\"case_id\": \"lcase_025\", \"case_number\": \"(2021)沪9024民初20888号\", \"title\": \"韦某诉某物流公司竞业限制纠纷案\", \"court_id\": \"arb_bj_chaoyang\", \"court_name\": \"北京市朝阳区劳动人事争议仲裁委员会\", \"case_type\": \"劳动争议\", \"cause\": \"竞业限制\", \"judgment_date\": \"2021-12-15\", \"parties\": \"原告：韦某（员工）；被告：某物流公司\", \"summary\": \"岗位不涉商业秘密，对其设定竞业限制超出必要范围。\", \"facts\": \"韦某2013年入职被告任项目经理，月工资14400元。约定竞业限制未支付补偿，员工主张补偿金，法院酌情支持。劳动者的岗位说明书载明其工作内容为客户咨询应答。\", \"reasoning\": \"竞业限制的适用主体限于负有保密义务的特定人员。原告的工作内容为受理客户来电与工单流转，未接触技术方案、客户名单或者定价策略，不属于适用范围。\", \"holding\": \"未接触技术方案、客户名单或定价策略的岗位，不属竞业限制适用主体。\", \"ruling\": \"一、被告支付韦某相关款项人民币115200元；二、案件受理费由被告负担。\", \"outcome\": \"部分支持\", \"keywords\": [\"竞业限制\", \"补偿金\", \"离职\"]}"
}

structuredContent:
{
  "result": "{\"case_id\": \"case_018\", \"case_number\": \"(2025)沪01民终05012号\", \"title\": \"某科技公司诉钱某竞业限制违约金纠纷上诉案\", \"court_id\": \"court_sh_no1\", \"court_name\": \"上海市第一中级人民法院\", \"case_type\": \"劳动争议\", \"cause\": \"竞业限制\", \"judgment_date\": \"2025-11-05\", \"parties\": \"上诉人：某科技公司；被上诉人：钱某（员工）\", \"summary\": \"公司主张员工违反竞业限制要求支付高额违约金，二审认定违约金过高予以酌减。\", \"facts\": \"钱某2019年入职被告任算法工程师，离职时约定竞业限制违约金为年薪三倍计180万元。公司主张其入职竞争对手要求支付违约金。一审酌减违约金。公司上诉要求全额。\", \"reasoning\": \"竞业限制违约金约定过分高于实际损失的，劳动者可请求适当减少。结合补偿金数额、违约情节及实际损失，原审酌减并无不当。\", \"holding\": \"竞业限制违约金过分高于用人单位实际损失的，人民法院可以根据当事人请求予以适当减少。\", \"ruling\": \"一、驳回上诉，维持原判（钱某支付竞业限制违约金人民币360000元）；二、二审受理费由上诉人负担。\", \"outcome\": \"驳回\", \"keywords\": [\"竞业限制\", \"违约金\", \"酌减\", \"算法工程师\", \"实际损失\"]}"
}

